#include <stdio.h>

#define MAXN 1005
#define INF 1e18

typedef struct {
    double p;
    double c;
} Bateria;

Bateria b[MAXN];
double dp[MAXN];

int main() {
    int n;
    double d;

    if (scanf("%d %lf", &n, &d) != 2) {
        return 0;
    }

    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &b[i].p, &b[i].c);
    }

    b[n].p = d;
    b[n].c = 0.0;

    for (int i = 1; i <= n; i++) {
        dp[i] = INF;
    }
    dp[0] = 0.0;

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j <= n; j++) {
            double dist = b[j].p - b[i].p;
            double cost = (dist * dist) / b[i].c;
            if (dp[i] + cost < dp[j]) {
                dp[j] = dp[i] + cost;
            }
        }
    }

    printf("%.3f\n", dp[n]);

    return 0;
}
